import React from 'react';

const Ahorro = ({ salary, monthlyExpenses }) => {
    return (
        <>
            <div className="ahorro-container">
                <h1 className="ahorro-title">Ahorro</h1>
                <div className="ahorro-content">
                    <p>Salario Mensual: {salary}</p>
                    <p>Gastos Mensuales: {monthlyExpenses}</p>
                    {/* Aquí puedes añadir más contenido específico del componente Ahorro */}
                </div>
            </div>
        </>
    );
};

export default Ahorro;
